const rawOutput = $input.first().json.output;

if (!rawOutput) {
  throw new Error("AI Evaluation output is empty");
}

const cleanedOutput = rawOutput
  .replace(/^\s*```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();

let result;

try {
  result = JSON.parse(cleanedOutput);
} catch (error) {
  throw new Error("Invalid AI Evaluation JSON: " + error.message);
}

// Normalize field names
const normalized = {};

for (const [key, value] of Object.entries(result)) {
  const normalizedKey = key
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, '_');

  normalized[normalizedKey] = value;
}

const dimensions = [
  "factual_accuracy",
  "completeness",
  "data_consistency",
  "relevance",
  "insight_quality",
  "html_quality"
];

const scores = {};
const summaries = {};
const dimensionIssues = {};

// Extract score, summary and issues from each dimension
for (const key of dimensions) {
  const dimension = normalized[key];

  const score = Number(
    dimension && typeof dimension === "object"
      ? dimension.score
      : dimension
  );

  if (!Number.isInteger(score) || score < 1 || score > 5) {
    throw new Error(
      `Invalid score for ${key}: ${
        dimension && typeof dimension === "object"
          ? JSON.stringify(dimension)
          : dimension
      }`
    );
  }

  scores[key] = score;

  summaries[key] =
    dimension && typeof dimension === "object"
      ? dimension.summary || ""
      : "";

  dimensionIssues[key] =
    dimension && typeof dimension === "object" &&
    Array.isArray(dimension.issues)
      ? dimension.issues
      : [];
}

// Extract missing sections from completeness
const completeness = normalized.completeness || {};

const missingSections =
  typeof completeness === "object" &&
  Array.isArray(completeness.missing_sections)
    ? completeness.missing_sections
    : [];

// Collect all dimension-specific issues
const allFindings = [
  ...Object.entries(dimensionIssues).flatMap(([dimension, issues]) =>
    issues.map(issue => ({
      dimension,
      issue
    }))
  ),
  ...(
    Array.isArray(normalized.data_consistency?.inconsistencies)
      ? normalized.data_consistency.inconsistencies.map(issue => ({
          dimension: "data_consistency",
          issue
        }))
      : []
  ),
  ...(
    Array.isArray(normalized.html_quality?.issues)
      ? normalized.html_quality.issues.map(issue => ({
          dimension: "html_quality",
          issue
        }))
      : []
  )
];

// Include other AI-reported findings
const existingFindings = Array.isArray(normalized.findings)
  ? normalized.findings
  : [];

const keyIssues = Array.isArray(normalized.key_issues)
  ? normalized.key_issues
  : [];

const overallScore =
  dimensions.reduce((sum, key) => sum + scores[key], 0) /
  dimensions.length;

const uniqueFindings = [
  ...new Set([
    ...allFindings.map(item => JSON.stringify(item)),
    ...existingFindings.map(item => JSON.stringify(item)),
    ...keyIssues.map(item => JSON.stringify(item))
  ])
].map(item => JSON.parse(item));

return {
  json: {
    ...normalized,
    ...scores,

    dimension_summaries: summaries,
    dimension_issues: dimensionIssues,

    findings: uniqueFindings,
    key_issues: keyIssues,
    missing_sections: missingSections,

    unsupported_claims: [],
    incorrect_claims: [],

    unsupported_claim_count: 0,
    incorrect_claim_count: 0,
    missing_section_count: missingSections.length,

    total_findings_count: uniqueFindings.length,
    total_report_issues: uniqueFindings.length,

    overall_score: Number(overallScore.toFixed(2)),
    overall_percentage: Number(
      (overallScore / 5 * 100).toFixed(2)
    ),

    evaluation_status: "Completed",
    evaluation_date: new Date().toISOString()
  }
};

const data = $json;

const dimensions = [
  "factual_accuracy",
  "completeness",
  "data_consistency",
  "relevance",
  "insight_quality",
  "html_quality"
];

const scores = dimensions.map(key => Number(data[key]));

for (const score of scores) {
  if (!Number.isInteger(score) || score < 1 || score > 5) {
    throw new Error("Invalid evaluation score: " + score);
  }
}

const averageScore =
  scores.reduce((sum, score) => sum + score, 0) / scores.length;

const unsupportedCount =
  Array.isArray(data.unsupported_claims)
    ? data.unsupported_claims.length
    : 0;

const incorrectCount =
  Array.isArray(data.incorrect_claims)
    ? data.incorrect_claims.length
    : 0;

const missingCount =
  Array.isArray(data.missing_sections)
    ? data.missing_sections.length
    : 0;

const issues = Array.isArray(data.issues)
  ? data.issues
  : [];

const totalRecommendationIssues = issues.length;

const totalReportIssues =
  unsupportedCount +
  incorrectCount +
  missingCount;

const totalFindings = Array.isArray(data.key_issues)
  ? data.key_issues.length
  : Array.isArray(data.findings)
    ? data.findings.length
    : Array.isArray(data.errors)
      ? data.errors.length
      : 0;

const metrics = {};

for (const key of dimensions) {
  metrics[key + "_percentage"] =
    Number(((data[key] / 5) * 100).toFixed(2));
}

return {
  json: {
    ...data,
    ...metrics,

    overall_score: Number(averageScore.toFixed(2)),
    overall_percentage: Number(
      ((averageScore / 5) * 100).toFixed(2)
    ),

    unsupported_claim_count: unsupportedCount,
    incorrect_claim_count: incorrectCount,
    missing_section_count: missingCount,

    total_findings_count: totalFindings,
    total_report_issues: totalReportIssues,
    total_recommendation_issues: totalRecommendationIssues,

    report_quality:
      averageScore >= 4.5 ? "Excellent" :
      averageScore >= 3.5 ? "Good" :
      averageScore >= 2.5 ? "Average" :
      averageScore >= 1.5 ? "Poor" : "Very Poor"
  }
};

const evaluation = $('ParseEvaluation').first().json;
const trigger = $('InputParser').first().json;

let rawOutput = $input.first().json.output;

if (!rawOutput) {
  throw new Error("AI Improvement Recommendations output is empty");
}

// Remove Markdown code fences if the AI includes them
rawOutput = rawOutput
  .replace(/^\s*```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();

let recommendations;

try {
  recommendations = JSON.parse(rawOutput);
} catch (error) {
  throw new Error("Invalid recommendations JSON: " + error.message);
}

return {
  json: {
    ...evaluation,
    ...recommendations,

    // Restore evaluation test information
    test_id: trigger.test_id,
    product_category: trigger.product_category,
    expected_sections: trigger.expected_sections,

    issues: Array.isArray(recommendations.issues)
      ? recommendations.issues : [],

    top_priorities: Array.isArray(recommendations.top_priorities)
      ? recommendations.top_priorities : [],

    overall_recommendations: Array.isArray(recommendations.overall_recommendations)
      ? recommendations.overall_recommendations : [],

    workflow_improvements: Array.isArray(recommendations.workflow_improvements)
      ? recommendations.workflow_improvements : [],

    improvement_summary: recommendations.improvement_summary || "",

    improvement_recommendations: JSON.stringify(recommendations)
  }
};

const data = $input.first().json;

// Temporary run number for testing
